import React, { useRef, useEffect, useState } from 'react';
import '../../styles/components/CreditsMap.css';

// Importamos las 4 imágenes de grass
import grass1 from '../../assets/images/tiles/grass/grass1.png';
import grass2 from '../../assets/images/tiles/grass/grass2.png';
import grass3 from '../../assets/images/tiles/grass/grass3.png';
import grass4 from '../../assets/images/tiles/grass/grass4.png';

interface CreditsMapProps {
  width: number;
  height: number;
}

const CreditsMap: React.FC<CreditsMapProps> = ({ width, height }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loading, setLoading] = useState(true);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [scale, setScale] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const [lastPosition, setLastPosition] = useState({ x: 0, y: 0 });
  
  // Cargar las imágenes para los tiles
  const tileImages = [grass1, grass2, grass3, grass4];
  const tileSize = 32;
  
  // Crear un mapa que determinará qué tipo de tile va en cada posición
  const generateMap = () => {
    const map: number[][] = [];
    
    // Usar un algoritmo simple de ruido para generar patrones naturales
    for (let y = 0; y < height; y++) {
      const row: number[] = [];
      for (let x = 0; x < width; x++) {
        // Crear un patrón semirandomizado basado en la posición
        // Esto crea patrones más naturales que el puro random
        const noise = Math.sin(x * 0.1) * Math.cos(y * 0.1) + Math.sin(x * 0.05 + y * 0.05);
        const normalizedNoise = (noise + 1) / 2; // Convertir a rango 0-1
        
        // Seleccionar tile basado en el ruido
        // Tiles más comunes (1 y 2) tienen más probabilidad que variantes especiales (3 y 4)
        let tileIndex;
        if (normalizedNoise < 0.6) {
          tileIndex = 0; // grass1 (más común)
        } else if (normalizedNoise < 0.85) {
          tileIndex = 1; // grass2 (común)
        } else if (normalizedNoise < 0.95) {
          tileIndex = 2; // grass3 (poco común)
        } else {
          tileIndex = 3; // grass4 (raro)
        }
        
        row.push(tileIndex);
      }
      map.push(row);
    }
    
    return map;
  };

  // Renderizar el mapa
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    
    // Cargar todas las imágenes
    const images: HTMLImageElement[] = [];
    let loadedImages = 0;
    
    tileImages.forEach((src, index) => {
      const img = new Image();
      img.src = src;
      img.onload = () => {
        loadedImages++;
        images[index] = img;
        
        // Una vez que todas las imágenes estén cargadas, dibujamos el mapa
        if (loadedImages === tileImages.length) {
          setLoading(false);
          
          // Generar mapa
          const map = generateMap();
          
          // Configurar canvas
          canvas.width = width * tileSize;
          canvas.height = height * tileSize;
          
          // Dibujar mapa
          for (let y = 0; y < height; y++) {
            for (let x = 0; x < width; x++) {
              const tileIndex = map[y][x];
              ctx.drawImage(
                images[tileIndex],
                x * tileSize, 
                y * tileSize,
                tileSize,
                tileSize
              );
            }
          }
        }
      };
      img.onerror = () => {
        console.error(`Failed to load image: ${src}`);
      };
    });
  }, [width, height]);
  
  // Manejar zoom y desplazamiento
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? 0.9 : 1.1;
      setScale(prevScale => Math.max(0.2, Math.min(5, prevScale * delta)));
    };
    
    const handleMouseDown = (e: MouseEvent) => {
      setIsDragging(true);
      setLastPosition({ x: e.clientX, y: e.clientY });
    };
    
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      
      const dx = e.clientX - lastPosition.x;
      const dy = e.clientY - lastPosition.y;
      
      setPosition(prev => ({
        x: prev.x + dx,
        y: prev.y + dy
      }));
      
      setLastPosition({ x: e.clientX, y: e.clientY });
    };
    
    const handleMouseUp = () => {
      setIsDragging(false);
    };
    
    canvas.addEventListener('wheel', handleWheel);
    canvas.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    
    return () => {
      canvas.removeEventListener('wheel', handleWheel);
      canvas.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, lastPosition]);
  
  return (
    <div className="credits-map-container">
      {loading ? (
        <div className="loading-map">Generando mundo...</div>
      ) : (
        <div className="map-wrapper">
          <div 
            className="map-view"
            style={{
              transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`
            }}
          >
            <canvas 
              ref={canvasRef}
              className="credits-map-canvas"
            />
          </div>
          <div className="map-controls">
            <p>Usa la rueda del ratón para hacer zoom, y arrastra para moverte</p>
            <button onClick={() => setScale(1)}>Resetear Zoom</button>
            <button onClick={() => setPosition({ x: 0, y: 0 })}>Centrar Mapa</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreditsMap;
